record.field:
action = False

LOCKED_STATES = ['printed', 'signed_uploaded', 'ministry_accredited', 'handover_ready', 'cancelled']

AR_DIGIT_MAP = {
    '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4',
    '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9',
    '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4',
    '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9',
}

BIDI_MARKS = ['\u200e', '\u200f', '\u202a', '\u202b', '\u202c', '\u202d', '\u202e', '\u2066', '\u2067', '\u2068', '\u2069']


def clean_text(value):
    if not value:
        return ''
    return str(value).strip()


def first_text(*values):
    for value in values:
        value = clean_text(value)
        if value:
            return value
    return ''


def has_field(record, field_name):
    return bool(record and field_name in record._fields)


def get_field(record, field_name):
    if has_field(record, field_name):
        return record[field_name]
    return False


def get_text_field(record, field_name):
    return clean_text(get_field(record, field_name))


def keep_or_fill_text(current, candidate):
    current = clean_text(current)
    if current:
        return current
    return clean_text(candidate) or False


def today_date():
    return datetime.date.today()


def arabic_weekday(date_value):
    if not date_value:
        return ''
    names = {
        0: 'الإثنين',
        1: 'الثلاثاء',
        2: 'الأربعاء',
        3: 'الخميس',
        4: 'الجمعة',
        5: 'السبت',
        6: 'الأحد',
    }
    try:
        return names.get(date_value.weekday(), '')
    except Exception:
        return ''


def now_dt():
    return datetime.datetime.now()


def normalize_gender(value):
    value = clean_text(value).lower()
    if value in ['male', 'm', 'ذكر', 'رجل']:
        return 'male'
    if value in ['female', 'f', 'أنثى', 'انثى', 'امرأة']:
        return 'female'
    return False


def normalize_phone(value):
    value = clean_text(value)
    if not value:
        return ''
    for mark in BIDI_MARKS:
        value = value.replace(mark, '')
    value = ''.join([AR_DIGIT_MAP.get(ch, ch) for ch in value])
    for ch in [' ', '\t', '\n', '\r', '-', '–', '—', '(', ')']:
        value = value.replace(ch, '')
    if value.endswith('+') and not value.startswith('+'):
        value = '+' + value[:-1]
    if value.startswith('00'):
        value = '+' + value[2:]
    return value


def normalize_blood_type(value):
    value = clean_text(value).upper().replace(' ', '')
    for mark in BIDI_MARKS:
        value = value.replace(mark, '')
    if value.endswith('+') and not value.startswith('+'):
        value = value[:-1] + '+'
    if value.endswith('-') and not value.startswith('-'):
        value = value[:-1] + '-'
    value = value.replace('٠', '0').replace('۰', '0')
    allowed = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-']
    if value in allowed:
        return value
    return clean_text(value)


def display_name_ar(record):
    if not record:
        return ''
    return first_text(
        get_text_field(record.with_context(lang='ar_001'), 'name'),
        get_text_field(record, 'name'),
        record.display_name
    )


def country_name_ar(country):
    if not country:
        return ''
    if getattr(country, '_name', ''):
        return first_text(
            country.with_context(lang='ar_001').name,
            country.name,
            country.display_name
        )
    return clean_text(country)


def find_pool(applicant):
    pool = False
    if has_field(applicant, 'x_pool_id') and applicant.x_pool_id:
        pool = applicant.x_pool_id.sudo()
    if not pool:
        pool = env['x_hr.pool'].sudo().search([('x_applicant_id', '=', applicant.id)], order='id desc', limit=1)
    if not pool:
        req = env['x_hr.pool_conversion_request'].sudo().search([('x_applicant_id', '=', applicant.id)], order='id desc', limit=1)
        if req and req.x_pool_id:
            pool = req.x_pool_id.sudo()
    return pool


def find_conversion_request(applicant, pool):
    req = False
    if has_field(applicant, 'x_pool_conversion_request_id') and applicant.x_pool_conversion_request_id:
        req = applicant.x_pool_conversion_request_id.sudo()
    if not req:
        req = env['x_hr.pool_conversion_request'].sudo().search([('x_applicant_id', '=', applicant.id)], order='id desc', limit=1)
    if not req and pool:
        req = env['x_hr.pool_conversion_request'].sudo().search([('x_pool_id', '=', pool.id)], order='id desc', limit=1)
    return req


def accepted_submission(applicant, codes):
    return env['x_hr.applicant_required_document_submission'].sudo().search([
        ('x_applicant_id', '=', applicant.id),
        ('x_state', '=', 'accepted'),
        ('x_document_code', 'in', codes),
    ], order='x_reviewed_on desc, x_submitted_on desc, id desc', limit=1)


def attachment_id(submission):
    if submission and submission.x_attachment_id:
        return submission.x_attachment_id.id
    return False


def identity_codes_for_source(source):
    source = clean_text(source)
    if source == 'passport':
        return ['passport']
    if source == 'driving_license':
        return ['driving_license']
    return ['id_card', 'national_id']


def source_for_identity_submission(submission):
    code = clean_text(submission.x_document_code) if submission else ''
    if code in ['id_card', 'national_id']:
        return 'id_card'
    if code == 'passport':
        return 'passport'
    if code == 'driving_license':
        return 'driving_license'
    return False


def selected_identity_submission(applicant, selected_source):
    selected_source = clean_text(selected_source)
    if selected_source:
        return accepted_submission(applicant, identity_codes_for_source(selected_source))
    for source in ['id_card', 'passport', 'driving_license']:
        sub = accepted_submission(applicant, identity_codes_for_source(source))
        if sub:
            return sub
    return False


def location_parent(location):
    if not location:
        return False
    for field_name in ['x_parent_id', 'x_parent_location_id', 'x_parent_location', 'parent_id', 'x_parent']:
        parent = get_field(location, field_name)
        if parent and getattr(parent, '_name', '') == getattr(location, '_name', ''):
            return parent
    return False


def location_level(location):
    if not location:
        return ''
    for field_name in ['x_location_type', 'x_type', 'x_level', 'x_location_level', 'type']:
        value = get_text_field(location, field_name).lower()
        if value:
            return value
    return ''


def is_level(location, level):
    value = location_level(location)
    if level == 'region':
        return value in ['region', 'regions', 'منطقة', 'region_level']
    if level == 'district':
        return value in ['district', 'districts', 'محلة', 'فرع بلدي', 'district_level']
    if level == 'municipality':
        return value in ['municipality', 'municipalities', 'بلدية', 'municipality_level']
    if level == 'locality':
        return value in ['locality', 'localities', 'محلة', 'منطقة سكنية', 'locality_level']
    return False


def complete_location_hierarchy(region, district, municipality, locality):
    # If a locality is available, walk upward to municipality/district/region when fields exist.
    if locality and not municipality:
        parent = location_parent(locality)
        if parent:
            municipality = parent
    if municipality and not district:
        parent = location_parent(municipality)
        if parent:
            district = parent
    if district and not region:
        parent = location_parent(district)
        if parent:
            region = parent
    # If the supplied municipality was actually a locality because of legacy naming, try one more upward pass.
    if municipality and is_level(municipality, 'locality') and not locality:
        locality = municipality
        municipality = location_parent(locality)
        if municipality and not district:
            district = location_parent(municipality)
        if district and not region:
            region = location_parent(district)
    return region, district, municipality, locality


def applicant_full_name(applicant, pool):
    parts = []
    for field_name in ['x_first_name_ar', 'x_father_name_ar', 'x_grandfather_name_ar', 'x_surname_ar']:
        value = first_text(get_text_field(applicant, field_name), get_text_field(pool, field_name))
        if value:
            parts.append(value)
    if parts:
        return ' '.join(parts)
    return first_text(applicant.partner_name, applicant.display_name)


def resolve_job(applicant, req):
    if applicant.job_id:
        return applicant.job_id
    if req and req.x_job_id:
        return req.x_job_id
    return False


def resolve_department(applicant, job):
    if has_field(applicant, 'department_id') and applicant.department_id:
        return applicant.department_id
    if job and has_field(job, 'department_id') and job.department_id:
        return job.department_id
    return False


def duration_label(contract):
    value = contract.x_contract_duration_value or 0
    unit = clean_text(contract.x_contract_duration_unit)
    if not value:
        return ''
    if unit == 'year':
        return str(value) + ' سنة'
    if unit == 'month':
        return str(value) + ' شهر'
    if unit == 'day':
        return str(value) + ' يوم'
    return str(value)


def sync_applicant(applicant, contract):
    vals = {
        'x_employment_contract_id': contract.id,
        'x_employment_contract_state': contract.x_state or False,
        'x_employment_contract_number': contract.x_contract_number or False,
        'x_employment_contract_date': contract.x_contract_date or False,
        'x_employment_contract_start_date': contract.x_contract_start_date or False,
        'x_employment_contract_end_date': contract.x_contract_end_date or False,
        'x_employment_contract_duration_label': duration_label(contract) or False,
        'x_employment_contract_monthly_wage': contract.x_monthly_wage_amount or 0.0,
        'x_employment_contract_job_id': contract.x_job_id.id if contract.x_job_id else False,
        'x_employment_contract_department_id': contract.x_department_id.id if contract.x_department_id else False,
        'x_employment_contract_document_id': contract.x_recruitment_document_id.id if contract.x_recruitment_document_id else False,
        'x_employment_contract_generated_attachment_id': contract.x_generated_attachment_id.id if contract.x_generated_attachment_id else False,
        'x_employment_contract_generated_on': contract.x_generated_on or False,
        'x_employment_contract_signed_attachment_id': contract.x_signed_attachment_id.id if contract.x_signed_attachment_id else False,
        'x_employment_contract_signed_uploaded_on': contract.x_signed_uploaded_on or False,
        'x_employment_contract_ministry_attachment_id': contract.x_ministry_accredited_attachment_id.id if contract.x_ministry_accredited_attachment_id else False,
        'x_employment_contract_ministry_accredited_on': contract.x_ministry_accredited_on or False,
        'x_employment_contract_board_decision_id': contract.x_board_decision_instance_id.id if contract.x_board_decision_instance_id else False,
    }
    if has_field(applicant, 'x_pool_id'):
        vals['x_pool_id'] = contract.x_pool_id.id if contract.x_pool_id else False
    if has_field(applicant, 'x_pool_conversion_request_id'):
        vals['x_pool_conversion_request_id'] = contract.x_conversion_request_id.id if contract.x_conversion_request_id else False
    applicant.write(vals)


def refresh_contract_snapshot(contract, applicant):
    if contract.x_state in LOCKED_STATES:
        return 'locked'

    pool = find_pool(applicant)
    req = find_conversion_request(applicant, pool)

    selected_source = clean_text(contract.x_identity_document_source)
    identity_sub = selected_identity_submission(applicant, selected_source)
    identity_source = selected_source or source_for_identity_submission(identity_sub)
    birth_sub = accepted_submission(applicant, ['birth_certificate'])
    residence_sub = accepted_submission(applicant, ['residence_certificate'])
    family_sub = accepted_submission(applicant, ['family_status'])
    health_sub = accepted_submission(applicant, ['health_certificate'])
    bank_sub = accepted_submission(applicant, ['bank_information'])
    qualification_sub = accepted_submission(applicant, ['qualification'])

    job = resolve_job(applicant, req)
    department = resolve_department(applicant, job)

    full_name = first_text(contract.x_full_name_ar, applicant_full_name(applicant, pool))
    first_name = first_text(contract.x_first_name_ar, get_text_field(applicant, 'x_first_name_ar'), get_text_field(pool, 'x_first_name_ar'))
    father_name = first_text(contract.x_father_name_ar, get_text_field(applicant, 'x_father_name_ar'), get_text_field(pool, 'x_father_name_ar'))
    grandfather_name = first_text(contract.x_grandfather_name_ar, get_text_field(applicant, 'x_grandfather_name_ar'), get_text_field(pool, 'x_grandfather_name_ar'))
    surname = first_text(contract.x_surname_ar, get_text_field(applicant, 'x_surname_ar'), get_text_field(pool, 'x_surname_ar'))

    national_id = first_text(contract.x_national_id, get_text_field(applicant, 'x_national_id'), get_text_field(pool, 'x_national_id'), identity_sub.x_document_number if identity_sub else '')
    gender = normalize_gender(first_text(contract.x_gender, get_text_field(applicant, 'x_gender'), get_text_field(pool, 'x_gender')))
    date_of_birth = contract.x_date_of_birth or get_field(applicant, 'x_date_of_birth') or get_field(pool, 'x_date_of_birth') or (birth_sub.x_date_of_birth if birth_sub and birth_sub.x_date_of_birth else False)

    nationality = first_text(contract.x_nationality_ar)
    if not nationality and pool and has_field(pool, 'x_nationality_id') and pool.x_nationality_id:
        nationality = country_name_ar(pool.x_nationality_id)

    region = contract.x_residence_region_id or get_field(applicant, 'x_residence_region_id') or get_field(pool, 'x_residence_region_id') or False
    district = contract.x_residence_district_id or get_field(applicant, 'x_residence_district_id') or get_field(pool, 'x_residence_district_id') or False
    municipality = contract.x_residence_municipality_id or get_field(applicant, 'x_residence_municipality_id') or get_field(pool, 'x_residence_municipality_id') or False
    locality = contract.x_residence_location_id or get_field(applicant, 'x_residence_location_id') or get_field(pool, 'x_residence_location_id') or False
    region, district, municipality, locality = complete_location_hierarchy(region, district, municipality, locality)

    preferred_phone = first_text(get_text_field(pool, 'x_phone'), get_text_field(applicant, 'partner_phone'), get_text_field(applicant, 'partner_mobile'))
    preferred_email = first_text(get_text_field(applicant, 'email_from'), get_text_field(pool, 'x_email'))
    contract_start = get_field(applicant, 'availability') or contract.x_contract_start_date or False
    contract_date = contract.x_contract_date or today_date()

    identity_number = contract.x_identity_document_number
    identity_issue_place = contract.x_identity_document_issue_place
    identity_issue_date = contract.x_identity_document_issue_date
    identity_expiry_date = contract.x_identity_document_expiry_date
    if identity_sub:
        identity_number = identity_sub.x_document_number or False
        identity_issue_place = identity_sub.x_place_of_issue or False
        identity_issue_date = identity_sub.x_issue_date or False
        identity_expiry_date = identity_sub.x_expiry_date or False

    vals = {
        'x_pool_id': pool.id if pool else False,
        'x_conversion_request_id': req.id if req else False,
        'x_contract_date': contract_date,
        'x_contract_day_ar': arabic_weekday(contract_date),
        'x_template_code': 'MCEP-HR-F-0005',
        'x_template_version': 'V.0.0.2015',
        'x_field_map_version': 'f0005-letter-overlay-v1',

        'x_company_name_ar': 'شركة مرسيليا للنظافة وحماية البيئة',
        'x_representative_name_ar': first_text(contract.x_representative_name_ar, 'حسين عبد الكريم حسين'),
        'x_representative_title_ar': first_text(contract.x_representative_title_ar, 'رئيس مجلس الإدارة'),
        'x_representative_nationality_ar': first_text(contract.x_representative_nationality_ar, 'ليبي'),

        'x_full_name_ar': full_name or False,
        'x_first_name_ar': first_name or False,
        'x_father_name_ar': father_name or False,
        'x_grandfather_name_ar': grandfather_name or False,
        'x_surname_ar': surname or False,
        'x_date_of_birth': date_of_birth or False,
        'x_gender': gender or False,
        'x_marital_status': first_text(contract.x_marital_status, get_text_field(pool, 'x_marital_status')) or False,
        'x_nationality_ar': nationality or False,
        'x_national_id': national_id or False,
        'x_email': first_text(contract.x_email, preferred_email) or False,
        'x_phone': normalize_phone(preferred_phone) or False,
        'x_mobile_1': normalize_phone(preferred_phone) or False,
        'x_mobile_2': normalize_phone(contract.x_mobile_2) or False,

        'x_identity_document_source': identity_source or False,
        'x_identity_document_number': identity_number or False,
        'x_identity_document_issue_place': identity_issue_place or False,
        'x_identity_document_issue_date': identity_issue_date or False,
        'x_identity_document_expiry_date': identity_expiry_date or False,

        'x_residence_region_id': region.id if region else False,
        'x_residence_district_id': district.id if district else False,
        'x_residence_municipality_id': municipality.id if municipality else False,
        'x_residence_location_id': locality.id if locality else False,
        'x_residence_address_text': first_text(contract.x_residence_address_text, get_text_field(applicant, 'x_address_text'), get_text_field(pool, 'x_address_text')) or False,
        'x_home_phone': normalize_phone(preferred_phone) or False,

        'x_bank_name': first_text(contract.x_bank_name, bank_sub.x_bank_name if bank_sub else '') or False,
        'x_bank_branch': first_text(contract.x_bank_branch, bank_sub.x_bank_branch if bank_sub else '') or False,
        'x_bank_account_number': first_text(contract.x_bank_account_number, bank_sub.x_account_number if bank_sub else '') or False,
        'x_iban': first_text(contract.x_iban, bank_sub.x_iban if bank_sub else '') or False,

        'x_qualification_type': first_text(contract.x_qualification_type, qualification_sub.x_qualification_type if qualification_sub else '') or False,
        'x_qualification_subject': first_text(contract.x_qualification_subject, qualification_sub.x_qualification_subject if qualification_sub else '') or False,
        'x_family_paper_number': first_text(contract.x_family_paper_number, family_sub.x_family_paper_number if family_sub else '') or False,
        'x_family_reference_number': first_text(contract.x_family_reference_number, family_sub.x_family_reference_number if family_sub else '') or False,
        'x_next_of_kin_name': first_text(contract.x_next_of_kin_name, family_sub.x_next_of_kin_name if family_sub else '') or False,
        'x_next_of_kin_phone': normalize_phone(family_sub.x_next_of_kin_phone if family_sub and family_sub.x_next_of_kin_phone else contract.x_next_of_kin_phone) or False,
        'x_blood_type': normalize_blood_type(health_sub.x_blood_type if health_sub and health_sub.x_blood_type else contract.x_blood_type) or False,

        'x_job_id': job.id if job else False,
        'x_job_title_ar': display_name_ar(job) if job else False,
        'x_department_id': department.id if department else False,
        'x_department_name_ar': display_name_ar(department) if department else False,
        'x_contract_start_date': contract_start or False,

        'x_identity_source_submission_id': identity_sub.id if identity_sub else False,
        'x_identity_source_attachment_id': attachment_id(identity_sub),
        'x_birth_source_submission_id': birth_sub.id if birth_sub else False,
        'x_birth_source_attachment_id': attachment_id(birth_sub),
        'x_residence_source_submission_id': residence_sub.id if residence_sub else False,
        'x_residence_source_attachment_id': attachment_id(residence_sub),
        'x_family_source_submission_id': family_sub.id if family_sub else False,
        'x_family_source_attachment_id': attachment_id(family_sub),
        'x_health_source_submission_id': health_sub.id if health_sub else False,
        'x_health_source_attachment_id': attachment_id(health_sub),
        'x_bank_source_submission_id': bank_sub.id if bank_sub else False,
        'x_bank_source_attachment_id': attachment_id(bank_sub),
        'x_qualification_source_submission_id': qualification_sub.id if qualification_sub else False,
        'x_qualification_source_attachment_id': attachment_id(qualification_sub),

        'x_snapshot_refreshed_on': now_dt(),
        'x_snapshot_refreshed_by_user_id': env.user.id,
    }

    vals['x_name'] = contract.x_name or ('عقد العمل - ' + (full_name or applicant.display_name or 'المتقدم'))

    missing = []
    for label, value in [
        ('الاسم الكامل', vals.get('x_full_name_ar')),
        ('الرقم الوطني', vals.get('x_national_id')),
        ('الجنس', vals.get('x_gender')),
        ('مستند الهوية', vals.get('x_identity_document_number')),
        ('المسمى الوظيفي', vals.get('x_job_title_ar')),
        ('الوحدة الإدارية', vals.get('x_department_name_ar')),
        ('تاريخ بداية العقد', vals.get('x_contract_start_date')),
        ('الأجر الشهري', contract.x_monthly_wage_amount),
    ]:
        if value in [False, None, '', 0, 0.0]:
            missing.append(label)

    if missing:
        vals['x_missing_snapshot_notes'] = 'قيم ناقصة قبل توليد العقد: ' + '، '.join(missing)
        if contract.x_state in [False, 'ready_to_render']:
            vals['x_state'] = 'draft_data'
    else:
        vals['x_missing_snapshot_notes'] = False
        if contract.x_state in [False, 'draft_data']:
            vals['x_state'] = 'ready_to_render'

    contract.write(vals)

    if has_field(applicant, 'x_pool_id') or has_field(applicant, 'x_pool_conversion_request_id'):
        bridge = {}
        if has_field(applicant, 'x_pool_id'):
            bridge['x_pool_id'] = pool.id if pool else False
        if has_field(applicant, 'x_pool_conversion_request_id'):
            bridge['x_pool_conversion_request_id'] = req.id if req else False
        if bridge:
            applicant.write(bridge)

    sync_applicant(applicant, contract)
    return 'updated'


def open_contract_action(contract):
    return {
        'type': 'ir.actions.act_window',
        'name': contract.x_name or 'بيانات العقد',
        'res_model': 'x_hr.applicant_employment_contract',
        'res_id': contract.id,
        'view_mode': 'form',
        'views': [(False, 'form')],
        'target': 'current',
    }


applicant = records.sudo()[:1]

if not applicant:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {'title': ui_text('No applicant'), 'message': ui_text('Open an applicant first.'), 'type': 'warning', 'sticky': False},
    }
else:
    contract = applicant.x_employment_contract_id or applicant.x_employment_contract_ids[:1]
    if not contract:
        pool = find_pool(applicant)
        req = find_conversion_request(applicant, pool)
        name = applicant_full_name(applicant, pool)
        contract = env['x_hr.applicant_employment_contract'].sudo().create({
            'x_name': 'عقد العمل - ' + (name or applicant.display_name or 'المتقدم'),
            'x_applicant_id': applicant.id,
            'x_pool_id': pool.id if pool else False,
            'x_conversion_request_id': req.id if req else False,
            'x_state': 'draft_data',
            'x_contract_date': today_date(),
            'x_contract_day_ar': arabic_weekday(today_date()),
            'x_template_code': 'MCEP-HR-F-0005',
            'x_template_version': 'V.0.0.2015',
            'x_field_map_version': 'f0005-letter-overlay-v1',
            'x_company_name_ar': 'شركة مرسيليا للنظافة وحماية البيئة',
            'x_representative_name_ar': 'حسين عبد الكريم حسين',
            'x_representative_title_ar': 'رئيس مجلس الإدارة',
            'x_representative_nationality_ar': 'ليبي',
            'x_handover_state': 'not_ready',
        })
        applicant.message_post(body='تم إنشاء سجل بيانات عقد العمل الرسمي وربطه بسجل المتقدم.')

    result = refresh_contract_snapshot(contract, applicant)

    if result == 'locked':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': ui_text('Contract locked'),
                'message': ui_text('The contract data cannot be updated after print confirmation or uploaded copies. Open the record for review only.'),
                'type': 'warning',
                'sticky': False,
                'next': open_contract_action(contract),
            },
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': ui_text('Contract data updated'),
                'message': contract.x_missing_snapshot_notes or 'تم تحديث بيانات العقد من المتقدم وخزان الموارد البشرية والمستندات المقبولة.',
                'type': 'success' if not contract.x_missing_snapshot_notes else 'warning',
                'sticky': False,
                'next': open_contract_action(contract),
            },
        }

action = False
applicant = records.sudo()[:1]

if not applicant:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {'title': ui_text('No applicant'), 'message': ui_text('Open an applicant first.'), 'type': 'warning', 'sticky': False},
    }
else:
    contract = applicant.x_employment_contract_id or applicant.x_employment_contract_ids[:1]
    if not contract:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {'title': ui_text('No contract'), 'message': ui_text('Create the contract first.'), 'type': 'warning', 'sticky': False},
        }
    else:
        action = {
            'type': 'ir.actions.act_window',
            'name': contract.x_name or 'بيانات العقد',
            'res_model': 'x_hr.applicant_employment_contract',
            'res_id': contract.id,
            'view_mode': 'form',
            'views': [(False, 'form')],
            'target': 'current',
        }

action = False

LOCKED_STATES = ['printed', 'signed_uploaded', 'ministry_accredited', 'handover_ready', 'cancelled']

AR_DIGIT_MAP = {
    '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4',
    '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9',
    '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4',
    '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9',
}

BIDI_MARKS = ['\u200e', '\u200f', '\u202a', '\u202b', '\u202c', '\u202d', '\u202e', '\u2066', '\u2067', '\u2068', '\u2069']


def clean_text(value):
    if not value:
        return ''
    return str(value).strip()


def first_text(*values):
    for value in values:
        value = clean_text(value)
        if value:
            return value
    return ''


def has_field(record, field_name):
    return bool(record and field_name in record._fields)


def get_field(record, field_name):
    if has_field(record, field_name):
        return record[field_name]
    return False


def get_text_field(record, field_name):
    return clean_text(get_field(record, field_name))


def keep_or_fill_text(current, candidate):
    current = clean_text(current)
    if current:
        return current
    return clean_text(candidate) or False


def today_date():
    return datetime.date.today()


def arabic_weekday(date_value):
    if not date_value:
        return ''
    names = {
        0: 'الإثنين',
        1: 'الثلاثاء',
        2: 'الأربعاء',
        3: 'الخميس',
        4: 'الجمعة',
        5: 'السبت',
        6: 'الأحد',
    }
    try:
        return names.get(date_value.weekday(), '')
    except Exception:
        return ''


def now_dt():
    return datetime.datetime.now()


def normalize_gender(value):
    value = clean_text(value).lower()
    if value in ['male', 'm', 'ذكر', 'رجل']:
        return 'male'
    if value in ['female', 'f', 'أنثى', 'انثى', 'امرأة']:
        return 'female'
    return False


def normalize_phone(value):
    value = clean_text(value)
    if not value:
        return ''
    for mark in BIDI_MARKS:
        value = value.replace(mark, '')
    value = ''.join([AR_DIGIT_MAP.get(ch, ch) for ch in value])
    for ch in [' ', '\t', '\n', '\r', '-', '–', '—', '(', ')']:
        value = value.replace(ch, '')
    if value.endswith('+') and not value.startswith('+'):
        value = '+' + value[:-1]
    if value.startswith('00'):
        value = '+' + value[2:]
    return value


def normalize_blood_type(value):
    value = clean_text(value).upper().replace(' ', '')
    for mark in BIDI_MARKS:
        value = value.replace(mark, '')
    if value.endswith('+') and not value.startswith('+'):
        value = value[:-1] + '+'
    if value.endswith('-') and not value.startswith('-'):
        value = value[:-1] + '-'
    value = value.replace('٠', '0').replace('۰', '0')
    allowed = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-']
    if value in allowed:
        return value
    return clean_text(value)


def display_name_ar(record):
    if not record:
        return ''
    return first_text(
        get_text_field(record.with_context(lang='ar_001'), 'name'),
        get_text_field(record, 'name'),
        record.display_name
    )


def country_name_ar(country):
    if not country:
        return ''
    if getattr(country, '_name', ''):
        return first_text(
            country.with_context(lang='ar_001').name,
            country.name,
            country.display_name
        )
    return clean_text(country)


def find_pool(applicant):
    pool = False
    if has_field(applicant, 'x_pool_id') and applicant.x_pool_id:
        pool = applicant.x_pool_id.sudo()
    if not pool:
        pool = env['x_hr.pool'].sudo().search([('x_applicant_id', '=', applicant.id)], order='id desc', limit=1)
    if not pool:
        req = env['x_hr.pool_conversion_request'].sudo().search([('x_applicant_id', '=', applicant.id)], order='id desc', limit=1)
        if req and req.x_pool_id:
            pool = req.x_pool_id.sudo()
    return pool


def find_conversion_request(applicant, pool):
    req = False
    if has_field(applicant, 'x_pool_conversion_request_id') and applicant.x_pool_conversion_request_id:
        req = applicant.x_pool_conversion_request_id.sudo()
    if not req:
        req = env['x_hr.pool_conversion_request'].sudo().search([('x_applicant_id', '=', applicant.id)], order='id desc', limit=1)
    if not req and pool:
        req = env['x_hr.pool_conversion_request'].sudo().search([('x_pool_id', '=', pool.id)], order='id desc', limit=1)
    return req


def accepted_submission(applicant, codes):
    return env['x_hr.applicant_required_document_submission'].sudo().search([
        ('x_applicant_id', '=', applicant.id),
        ('x_state', '=', 'accepted'),
        ('x_document_code', 'in', codes),
    ], order='x_reviewed_on desc, x_submitted_on desc, id desc', limit=1)


def attachment_id(submission):
    if submission and submission.x_attachment_id:
        return submission.x_attachment_id.id
    return False


def identity_codes_for_source(source):
    source = clean_text(source)
    if source == 'passport':
        return ['passport']
    if source == 'driving_license':
        return ['driving_license']
    return ['id_card', 'national_id']


def source_for_identity_submission(submission):
    code = clean_text(submission.x_document_code) if submission else ''
    if code in ['id_card', 'national_id']:
        return 'id_card'
    if code == 'passport':
        return 'passport'
    if code == 'driving_license':
        return 'driving_license'
    return False


def selected_identity_submission(applicant, selected_source):
    selected_source = clean_text(selected_source)
    if selected_source:
        return accepted_submission(applicant, identity_codes_for_source(selected_source))
    for source in ['id_card', 'passport', 'driving_license']:
        sub = accepted_submission(applicant, identity_codes_for_source(source))
        if sub:
            return sub
    return False


def location_parent(location):
    if not location:
        return False
    for field_name in ['x_parent_id', 'x_parent_location_id', 'x_parent_location', 'parent_id', 'x_parent']:
        parent = get_field(location, field_name)
        if parent and getattr(parent, '_name', '') == getattr(location, '_name', ''):
            return parent
    return False


def location_level(location):
    if not location:
        return ''
    for field_name in ['x_location_type', 'x_type', 'x_level', 'x_location_level', 'type']:
        value = get_text_field(location, field_name).lower()
        if value:
            return value
    return ''


def is_level(location, level):
    value = location_level(location)
    if level == 'region':
        return value in ['region', 'regions', 'منطقة', 'region_level']
    if level == 'district':
        return value in ['district', 'districts', 'محلة', 'فرع بلدي', 'district_level']
    if level == 'municipality':
        return value in ['municipality', 'municipalities', 'بلدية', 'municipality_level']
    if level == 'locality':
        return value in ['locality', 'localities', 'محلة', 'منطقة سكنية', 'locality_level']
    return False


def complete_location_hierarchy(region, district, municipality, locality):
    # If a locality is available, walk upward to municipality/district/region when fields exist.
    if locality and not municipality:
        parent = location_parent(locality)
        if parent:
            municipality = parent
    if municipality and not district:
        parent = location_parent(municipality)
        if parent:
            district = parent
    if district and not region:
        parent = location_parent(district)
        if parent:
            region = parent
    # If the supplied municipality was actually a locality because of legacy naming, try one more upward pass.
    if municipality and is_level(municipality, 'locality') and not locality:
        locality = municipality
        municipality = location_parent(locality)
        if municipality and not district:
            district = location_parent(municipality)
        if district and not region:
            region = location_parent(district)
    return region, district, municipality, locality


def applicant_full_name(applicant, pool):
    parts = []
    for field_name in ['x_first_name_ar', 'x_father_name_ar', 'x_grandfather_name_ar', 'x_surname_ar']:
        value = first_text(get_text_field(applicant, field_name), get_text_field(pool, field_name))
        if value:
            parts.append(value)
    if parts:
        return ' '.join(parts)
    return first_text(applicant.partner_name, applicant.display_name)


def resolve_job(applicant, req):
    if applicant.job_id:
        return applicant.job_id
    if req and req.x_job_id:
        return req.x_job_id
    return False


def resolve_department(applicant, job):
    if has_field(applicant, 'department_id') and applicant.department_id:
        return applicant.department_id
    if job and has_field(job, 'department_id') and job.department_id:
        return job.department_id
    return False


def duration_label(contract):
    value = contract.x_contract_duration_value or 0
    unit = clean_text(contract.x_contract_duration_unit)
    if not value:
        return ''
    if unit == 'year':
        return str(value) + ' سنة'
    if unit == 'month':
        return str(value) + ' شهر'
    if unit == 'day':
        return str(value) + ' يوم'
    return str(value)


def sync_applicant(applicant, contract):
    vals = {
        'x_employment_contract_id': contract.id,
        'x_employment_contract_state': contract.x_state or False,
        'x_employment_contract_number': contract.x_contract_number or False,
        'x_employment_contract_date': contract.x_contract_date or False,
        'x_employment_contract_start_date': contract.x_contract_start_date or False,
        'x_employment_contract_end_date': contract.x_contract_end_date or False,
        'x_employment_contract_duration_label': duration_label(contract) or False,
        'x_employment_contract_monthly_wage': contract.x_monthly_wage_amount or 0.0,
        'x_employment_contract_job_id': contract.x_job_id.id if contract.x_job_id else False,
        'x_employment_contract_department_id': contract.x_department_id.id if contract.x_department_id else False,
        'x_employment_contract_document_id': contract.x_recruitment_document_id.id if contract.x_recruitment_document_id else False,
        'x_employment_contract_generated_attachment_id': contract.x_generated_attachment_id.id if contract.x_generated_attachment_id else False,
        'x_employment_contract_generated_on': contract.x_generated_on or False,
        'x_employment_contract_signed_attachment_id': contract.x_signed_attachment_id.id if contract.x_signed_attachment_id else False,
        'x_employment_contract_signed_uploaded_on': contract.x_signed_uploaded_on or False,
        'x_employment_contract_ministry_attachment_id': contract.x_ministry_accredited_attachment_id.id if contract.x_ministry_accredited_attachment_id else False,
        'x_employment_contract_ministry_accredited_on': contract.x_ministry_accredited_on or False,
        'x_employment_contract_board_decision_id': contract.x_board_decision_instance_id.id if contract.x_board_decision_instance_id else False,
    }
    if has_field(applicant, 'x_pool_id'):
        vals['x_pool_id'] = contract.x_pool_id.id if contract.x_pool_id else False
    if has_field(applicant, 'x_pool_conversion_request_id'):
        vals['x_pool_conversion_request_id'] = contract.x_conversion_request_id.id if contract.x_conversion_request_id else False
    applicant.write(vals)


def refresh_contract_snapshot(contract, applicant):
    if contract.x_state in LOCKED_STATES:
        return 'locked'

    pool = find_pool(applicant)
    req = find_conversion_request(applicant, pool)

    selected_source = clean_text(contract.x_identity_document_source)
    identity_sub = selected_identity_submission(applicant, selected_source)
    identity_source = selected_source or source_for_identity_submission(identity_sub)
    birth_sub = accepted_submission(applicant, ['birth_certificate'])
    residence_sub = accepted_submission(applicant, ['residence_certificate'])
    family_sub = accepted_submission(applicant, ['family_status'])
    health_sub = accepted_submission(applicant, ['health_certificate'])
    bank_sub = accepted_submission(applicant, ['bank_information'])
    qualification_sub = accepted_submission(applicant, ['qualification'])

    job = resolve_job(applicant, req)
    department = resolve_department(applicant, job)

    full_name = first_text(contract.x_full_name_ar, applicant_full_name(applicant, pool))
    first_name = first_text(contract.x_first_name_ar, get_text_field(applicant, 'x_first_name_ar'), get_text_field(pool, 'x_first_name_ar'))
    father_name = first_text(contract.x_father_name_ar, get_text_field(applicant, 'x_father_name_ar'), get_text_field(pool, 'x_father_name_ar'))
    grandfather_name = first_text(contract.x_grandfather_name_ar, get_text_field(applicant, 'x_grandfather_name_ar'), get_text_field(pool, 'x_grandfather_name_ar'))
    surname = first_text(contract.x_surname_ar, get_text_field(applicant, 'x_surname_ar'), get_text_field(pool, 'x_surname_ar'))

    national_id = first_text(contract.x_national_id, get_text_field(applicant, 'x_national_id'), get_text_field(pool, 'x_national_id'), identity_sub.x_document_number if identity_sub else '')
    gender = normalize_gender(first_text(contract.x_gender, get_text_field(applicant, 'x_gender'), get_text_field(pool, 'x_gender')))
    date_of_birth = contract.x_date_of_birth or get_field(applicant, 'x_date_of_birth') or get_field(pool, 'x_date_of_birth') or (birth_sub.x_date_of_birth if birth_sub and birth_sub.x_date_of_birth else False)

    nationality = first_text(contract.x_nationality_ar)
    if not nationality and pool and has_field(pool, 'x_nationality_id') and pool.x_nationality_id:
        nationality = country_name_ar(pool.x_nationality_id)

    region = contract.x_residence_region_id or get_field(applicant, 'x_residence_region_id') or get_field(pool, 'x_residence_region_id') or False
    district = contract.x_residence_district_id or get_field(applicant, 'x_residence_district_id') or get_field(pool, 'x_residence_district_id') or False
    municipality = contract.x_residence_municipality_id or get_field(applicant, 'x_residence_municipality_id') or get_field(pool, 'x_residence_municipality_id') or False
    locality = contract.x_residence_location_id or get_field(applicant, 'x_residence_location_id') or get_field(pool, 'x_residence_location_id') or False
    region, district, municipality, locality = complete_location_hierarchy(region, district, municipality, locality)

    preferred_phone = first_text(get_text_field(pool, 'x_phone'), get_text_field(applicant, 'partner_phone'), get_text_field(applicant, 'partner_mobile'))
    preferred_email = first_text(get_text_field(applicant, 'email_from'), get_text_field(pool, 'x_email'))
    contract_start = get_field(applicant, 'availability') or contract.x_contract_start_date or False
    contract_date = contract.x_contract_date or today_date()

    identity_number = contract.x_identity_document_number
    identity_issue_place = contract.x_identity_document_issue_place
    identity_issue_date = contract.x_identity_document_issue_date
    identity_expiry_date = contract.x_identity_document_expiry_date
    if identity_sub:
        identity_number = identity_sub.x_document_number or False
        identity_issue_place = identity_sub.x_place_of_issue or False
        identity_issue_date = identity_sub.x_issue_date or False
        identity_expiry_date = identity_sub.x_expiry_date or False

    vals = {
        'x_pool_id': pool.id if pool else False,
        'x_conversion_request_id': req.id if req else False,
        'x_contract_date': contract_date,
        'x_contract_day_ar': arabic_weekday(contract_date),
        'x_template_code': 'MCEP-HR-F-0005',
        'x_template_version': 'V.0.0.2015',
        'x_field_map_version': 'f0005-letter-overlay-v1',

        'x_company_name_ar': 'شركة مرسيليا للنظافة وحماية البيئة',
        'x_representative_name_ar': first_text(contract.x_representative_name_ar, 'حسين عبد الكريم حسين'),
        'x_representative_title_ar': first_text(contract.x_representative_title_ar, 'رئيس مجلس الإدارة'),
        'x_representative_nationality_ar': first_text(contract.x_representative_nationality_ar, 'ليبي'),

        'x_full_name_ar': full_name or False,
        'x_first_name_ar': first_name or False,
        'x_father_name_ar': father_name or False,
        'x_grandfather_name_ar': grandfather_name or False,
        'x_surname_ar': surname or False,
        'x_date_of_birth': date_of_birth or False,
        'x_gender': gender or False,
        'x_marital_status': first_text(contract.x_marital_status, get_text_field(pool, 'x_marital_status')) or False,
        'x_nationality_ar': nationality or False,
        'x_national_id': national_id or False,
        'x_email': first_text(contract.x_email, preferred_email) or False,
        'x_phone': normalize_phone(preferred_phone) or False,
        'x_mobile_1': normalize_phone(preferred_phone) or False,
        'x_mobile_2': normalize_phone(contract.x_mobile_2) or False,

        'x_identity_document_source': identity_source or False,
        'x_identity_document_number': identity_number or False,
        'x_identity_document_issue_place': identity_issue_place or False,
        'x_identity_document_issue_date': identity_issue_date or False,
        'x_identity_document_expiry_date': identity_expiry_date or False,

        'x_residence_region_id': region.id if region else False,
        'x_residence_district_id': district.id if district else False,
        'x_residence_municipality_id': municipality.id if municipality else False,
        'x_residence_location_id': locality.id if locality else False,
        'x_residence_address_text': first_text(contract.x_residence_address_text, get_text_field(applicant, 'x_address_text'), get_text_field(pool, 'x_address_text')) or False,
        'x_home_phone': normalize_phone(preferred_phone) or False,

        'x_bank_name': first_text(contract.x_bank_name, bank_sub.x_bank_name if bank_sub else '') or False,
        'x_bank_branch': first_text(contract.x_bank_branch, bank_sub.x_bank_branch if bank_sub else '') or False,
        'x_bank_account_number': first_text(contract.x_bank_account_number, bank_sub.x_account_number if bank_sub else '') or False,
        'x_iban': first_text(contract.x_iban, bank_sub.x_iban if bank_sub else '') or False,

        'x_qualification_type': first_text(contract.x_qualification_type, qualification_sub.x_qualification_type if qualification_sub else '') or False,
        'x_qualification_subject': first_text(contract.x_qualification_subject, qualification_sub.x_qualification_subject if qualification_sub else '') or False,
        'x_family_paper_number': first_text(contract.x_family_paper_number, family_sub.x_family_paper_number if family_sub else '') or False,
        'x_family_reference_number': first_text(contract.x_family_reference_number, family_sub.x_family_reference_number if family_sub else '') or False,
        'x_next_of_kin_name': first_text(contract.x_next_of_kin_name, family_sub.x_next_of_kin_name if family_sub else '') or False,
        'x_next_of_kin_phone': normalize_phone(family_sub.x_next_of_kin_phone if family_sub and family_sub.x_next_of_kin_phone else contract.x_next_of_kin_phone) or False,
        'x_blood_type': normalize_blood_type(health_sub.x_blood_type if health_sub and health_sub.x_blood_type else contract.x_blood_type) or False,

        'x_job_id': job.id if job else False,
        'x_job_title_ar': display_name_ar(job) if job else False,
        'x_department_id': department.id if department else False,
        'x_department_name_ar': display_name_ar(department) if department else False,
        'x_contract_start_date': contract_start or False,

        'x_identity_source_submission_id': identity_sub.id if identity_sub else False,
        'x_identity_source_attachment_id': attachment_id(identity_sub),
        'x_birth_source_submission_id': birth_sub.id if birth_sub else False,
        'x_birth_source_attachment_id': attachment_id(birth_sub),
        'x_residence_source_submission_id': residence_sub.id if residence_sub else False,
        'x_residence_source_attachment_id': attachment_id(residence_sub),
        'x_family_source_submission_id': family_sub.id if family_sub else False,
        'x_family_source_attachment_id': attachment_id(family_sub),
        'x_health_source_submission_id': health_sub.id if health_sub else False,
        'x_health_source_attachment_id': attachment_id(health_sub),
        'x_bank_source_submission_id': bank_sub.id if bank_sub else False,
        'x_bank_source_attachment_id': attachment_id(bank_sub),
        'x_qualification_source_submission_id': qualification_sub.id if qualification_sub else False,
        'x_qualification_source_attachment_id': attachment_id(qualification_sub),

        'x_snapshot_refreshed_on': now_dt(),
        'x_snapshot_refreshed_by_user_id': env.user.id,
    }

    vals['x_name'] = contract.x_name or ('عقد العمل - ' + (full_name or applicant.display_name or 'المتقدم'))

    missing = []
    for label, value in [
        ('الاسم الكامل', vals.get('x_full_name_ar')),
        ('الرقم الوطني', vals.get('x_national_id')),
        ('الجنس', vals.get('x_gender')),
        ('مستند الهوية', vals.get('x_identity_document_number')),
        ('المسمى الوظيفي', vals.get('x_job_title_ar')),
        ('الوحدة الإدارية', vals.get('x_department_name_ar')),
        ('تاريخ بداية العقد', vals.get('x_contract_start_date')),
        ('الأجر الشهري', contract.x_monthly_wage_amount),
    ]:
        if value in [False, None, '', 0, 0.0]:
            missing.append(label)

    if missing:
        vals['x_missing_snapshot_notes'] = 'قيم ناقصة قبل توليد العقد: ' + '، '.join(missing)
        if contract.x_state in [False, 'ready_to_render']:
            vals['x_state'] = 'draft_data'
    else:
        vals['x_missing_snapshot_notes'] = False
        if contract.x_state in [False, 'draft_data']:
            vals['x_state'] = 'ready_to_render'

    contract.write(vals)

    if has_field(applicant, 'x_pool_id') or has_field(applicant, 'x_pool_conversion_request_id'):
        bridge = {}
        if has_field(applicant, 'x_pool_id'):
            bridge['x_pool_id'] = pool.id if pool else False
        if has_field(applicant, 'x_pool_conversion_request_id'):
            bridge['x_pool_conversion_request_id'] = req.id if req else False
        if bridge:
            applicant.write(bridge)

    sync_applicant(applicant, contract)
    return 'updated'


def open_contract_action(contract):
    return {
        'type': 'ir.actions.act_window',
        'name': contract.x_name or 'بيانات العقد',
        'res_model': 'x_hr.applicant_employment_contract',
        'res_id': contract.id,
        'view_mode': 'form',
        'views': [(False, 'form')],
        'target': 'current',
    }


applicant = records.sudo()[:1]

